 private void information(){JSONObject peer=state.optJSONObject("peer");String details="仅发送你在这里主动写下的内容，个人历史不会上传。文字在双方设备解密，双人内容保存在本机加密资料库。\n\n打开此页面会自动收取；也可手动刷新。离线消息中转保留7天。网络支持时可点对点通信，直连失败会使用加密中转。\n\n邀请码有效期十分钟。双方通过见面或可信通话逐组核对安全码后，才能建立连接。";if(peer!=null)details+="\n\n安全码\n"+safety(peer);AlertDialog d=new LanguageDialog(a).setTitle("隐私与连接安全").setMessage(details).setPositiveButton("知道了",null).create();a.dialogs.add(d);d.show();WorkbuddyUi.decorate(d);}
