 private void renderMessages(){JSONArray messages=state.optJSONArray("inbox");LinearLayout box=a.column();TextView heading=a.text("最近的留言",15,Ui.INK);heading.setTypeface(null,Typeface.BOLD);box.addView(heading);int count=0;if(messages!=null)for(int i=Math.max(0,messages.length()-30);i<messages.length();i++){JSONObject row=messages.optJSONObject(i),p=row==null?null:row.optJSONObject("payload");if(p==null||!"text".equals(p.optString("kind")))continue;count++;boolean mine=state.optString("id").equals(row.optString("sender"));LinearLayout line=new LinearLayout(a);line.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);line.setPadding(0,a.dp(5),0,a.dp(5));TextView bubble=a.text(Language.raw(p.optString("text")),15,mine?Ui.ON_ACCENT:Ui.INK);bubble.setPadding(a.dp(14),a.dp(10),a.dp(14),a.dp(10));bubble.setMaxWidth(a.dp(270));bubble.setBackground(Ui.stroke(mine?Ui.BERRY:Ui.SURFACE,mine?Ui.BERRY:Ui.BORDER,18,a));bubble.setContentDescription(Language.ui((mine?"你：":"伴侣：")+Language.raw(p.optString("text"))));line.addView(bubble);box.addView(line);long at=row.optLong("at");if(at>0){TextView time=a.text(java.time.Instant.ofEpochMilli(at).atZone(java.time.ZoneId.systemDefault()).toLocalDateTime().toString().replace("T"," "),11,Ui.MUTED);time.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);box.addView(time);}if(mine){JSONArray out=state.optJSONArray("outbox");boolean queued=false;if(out!=null)for(int q=0;q<out.length();q++)if(row.optString("id").equals(out.optJSONObject(q).optString("id")))queued=true;if(queued){Button retry=control(busy?"发送中…":"待发送 · 重试",()->refresh(),false);box.addView(retry);}}}if(count==0){TextView empty=a.text("还没有留言",13,Ui.MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(0,a.dp(22),0,a.dp(26));box.addView(empty);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,a.dp(14));box.setLayoutParams(lp);addView(box);}
 // Shared objects are derived from authenticated encrypted messages, independently of personal events.
 private void apply(JSONObject c,JSONObject p,String sender)throws Exception{if("sharedRecord".equals(p.optString("kind")))SharedCoupleRecords.apply(c,p,sender);else CoupleProposal.apply(c,p,sender);}
 static JSONObject operation(JSONObject c,String type,String subject,String source,JSONObject data,String action)throws Exception{return new JSONObject().put("kind","sharedRecord").put("recordType",type).put("subject",subject).put("sourceId",source).put("data",data).put("action",action).put("operationId",UUID.randomUUID().toString()).put("clock",nextClock(c));}
 private static long nextClock(JSONObject c){long clock=1;JSONObject all=c.optJSONObject("sharedRecords");if(all!=null){Iterator<String> ids=all.keys();while(ids.hasNext()){JSONObject item=all.optJSONObject(ids.next());for(String section:new String[]{"versions","interactions"}){JSONObject values=item.optJSONObject(section);if(values==null)continue;Iterator<String> keys=values.keys();while(keys.hasNext()){Object value=values.opt(keys.next());String version=value instanceof JSONObject?((JSONObject)value).optString("version"):String.valueOf(value);try{clock=Math.max(clock,Long.parseLong(version.substring(0,19))+1);}catch(Exception ignored){}}}}}return clock;}
 static void preview(MainActivity a,JSONObject raw,String type,boolean partner){a.attempt(()->{JSONObject c=a.root.optJSONObject("couple");if(c==null||c.optJSONObject("peer")==null){Toast.makeText(a,Language.ui("请先在爱人页完成安全连接"),Toast.LENGTH_LONG).show();return;}String subject=partner?c.getJSONObject("peer").getString("id"):c.getString("id"),source=subject+":"+raw.getString("id");JSONObject shares=c.optJSONObject("sharedRecords"),previous=shares==null?null:shares.optJSONObject(SharedCoupleRecords.key(type,subject,source,raw));if(previous!=null&&previous.optBoolean("withdrawn")){AlertDialog withdrawn=new LanguageDialog(a).setTitle("共享副本已撤回").setMessage("这条共享副本已撤回；原记录保留，目前不能重新分享同一条。").setPositiveButton("知道了",null).create();a.dialogs.add(withdrawn);withdrawn.show();WorkbuddyUi.decorate(withdrawn);return;}LinearLayout box=a.column();box.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(8));TextView details=a.text("",14,Ui.INK);box.addView(details);CheckBox location=new LanguageViews.Check(a);location.setText("本次也分享地点与坐标");Ui.styleToggle(location);if("sex".equals(type))box.addView(location);Runnable update=()->a.attempt(()->details.setText(previewText(SharedCoupleRecords.snapshot(raw,type,location.isChecked()))));update.run();location.setOnCheckedChangeListener((v,on)->update.run());box.addView(a.text(("period".equals(type)?(partner?"分享 TA 的经期共享副本。":"分享你的经期共享副本。"):"地点默认不选；私人备注不分享。")+"\n只分享以上字段，备注和其他未知字段不发送。个人原记录保持不变。历史不会自动分享。",12,Ui.MUTED));AlertDialog d=new LanguageDialog(a).setTitle("period".equals(type)?"分享这段经期":"分享这次亲密记录").setView(scrollPreview(a,box)).setNegativeButton("取消",null).setPositiveButton("确认分享",(v,w)->a.attempt(()->{JSONObject latest=a.vault.read().getJSONObject("couple"),clean=SharedCoupleRecords.snapshot(raw,type,location.isChecked()),payload=operation(latest,type,subject,source,clean,"share").put("includeLocation",location.isChecked());if(!"爱人".equals(a.tab)||a.workbuddyCoupleView==null){a.tab="爱人";a.show();}a.workbuddyCoupleView.send(payload);})).create();a.dialogs.add(d);d.show();WorkbuddyUi.decorate(d);});}
