 private static String previewText(JSONObject data){List<String> lines=new ArrayList<>();String[][] labels={{"date","日期"},{"time","时间"},{"durationMillis","时长（毫秒）"},{"method","方式"},{"rating","评分"},{"protection","保护措施"},{"outcomes","射精情况"},{"positions","姿势"},{"vocalLevel","声音"},{"selfOrgasm","本人高潮"},{"partnerOrgasm","对方高潮"},{"selfOrgasmCount","本人高潮次数"},{"partnerOrgasmCount","对方高潮次数"},{"start","开始"},{"end","结束"},{"flow","经量"},{"pain","疼痛"},{"place","地点"},{"latitude","纬度"},{"longitude","经度"},{"locationAccuracy","定位精度"},{"locationCapturedAt","定位时间"}};for(String[] label:labels)if(data.has(label[0])&&!(data.isNull(label[0])&&Arrays.asList("place","latitude","longitude","locationAccuracy","locationCapturedAt").contains(label[0])))lines.add(label[1]+"："+(data.isNull(label[0])?"未填写":label[0].equals("place")?Language.raw(data.optString(label[0])):data.opt(label[0])));return String.join("\n",lines);}
